package com.bank.safestop.ledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

// The shared state that must stay consistent. Total money is an invariant:
// the sum of all balances must never change due to a transfer.
public class Ledger {
    private final Map<String, BigDecimal> balances = new HashMap<>();

    public Ledger() {
        balances.put("SAV2001", new BigDecimal("1000000")); // Rajesh
        balances.put("CUR3001", new BigDecimal("250000"));  // Priya
    }

    // synchronized so debit+credit are atomic under the SAME monitor.
    public synchronized void transfer(String from, String to, BigDecimal amount) {
        BigDecimal f = balances.get(from).subtract(amount); // debit
        balances.put(from, f);
        // If Thread.stop fired HERE, it would release this monitor with
        // money debited but NOT yet credited — the corruption stop causes.
        BigDecimal t = balances.get(to).add(amount);        // credit
        balances.put(to, t);
    }

    public synchronized BigDecimal total() {
        return balances.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    public synchronized BigDecimal balanceOf(String id) { return balances.get(id); }
}
