package com.bank.safestop.worker;

import com.bank.safestop.ledger.Ledger;

import java.math.BigDecimal;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

// The SAFE replacement for stop/suspend/resume:
//  - stopping: check the interrupt flag BETWEEN whole transfers
//  - pausing:  wait()/notifyAll() which RELEASES the lock while paused
public class TransferWorker implements Runnable {
    private static final Logger log = Logger.getLogger(TransferWorker.class.getName());
    private final Ledger ledger;
    private final Object pauseLock = new Object();
    private volatile boolean paused = false;
    private final AtomicInteger completed = new AtomicInteger();

    public TransferWorker(Ledger ledger) { this.ledger = ledger; }

    @Override
    public void run() {
        log.info("TransferWorker started");
        try {
            // Flag is checked only between whole transfers → always a safe point.
            while (!Thread.currentThread().isInterrupted()) {
                awaitIfPaused();                 // safe pause (lock released)
                ledger.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
                ledger.transfer("CUR3001", "SAV2001", new BigDecimal("50000"));
                completed.incrementAndGet();
                Thread.sleep(2);                 // yield; throws on interrupt
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();   // restore flag, stop cleanly
            log.info("TransferWorker interrupted — stopping at a SAFE point");
        }
        log.info(() -> "TransferWorker stopped. completedPairs=" + completed.get()
                + " ledgerTotal=" + ledger.total());
    }

    // Safe pause: the thread WAITS, releasing pauseLock so nobody is blocked.
    private void awaitIfPaused() throws InterruptedException {
        synchronized (pauseLock) {
            while (paused) pauseLock.wait();      // releases lock while waiting
        }
    }

    public void pause() {
        paused = true;
        log.info("pause() requested");
    }

    public void resumeWork() {
        synchronized (pauseLock) {
            paused = false;
            pauseLock.notifyAll();                // wake the waiting worker
        }
        log.info("resumeWork() requested");
    }

    public int completedPairs() { return completed.get(); }
}
