package com.bank.safestop.explain;

import java.util.logging.Logger;

// Documents WHY the deprecated methods are unsafe. It does not call them
// (they are unsafe by definition); it simulates the failure sequence.
public class UnsafeStopExplainer {
    private static final Logger log = Logger.getLogger(UnsafeStopExplainer.class.getName());

    public String whyStopIsUnsafe() {
        String reason =
            "Thread.stop throws ThreadDeath at an ARBITRARY instruction and "
          + "RELEASES all held monitors. If it fires between debit and credit, "
          + "the lock is dropped with money gone from one account and not in the "
          + "other, and the next thread reads an UNBALANCED ledger. Silent corruption.";
        log.severe(reason);
        return reason;
    }

    public String whySuspendIsUnsafe() {
        String reason =
            "Thread.suspend freezes the thread but KEEPS its locks. If it is "
          + "suspended while holding the ledger lock, any other thread needing "
          + "that lock blocks forever, and the resumer may itself need the lock. "
          + "Classic DEADLOCK — this is why suspend/resume were deprecated together.";
        log.severe(reason);
        return reason;
    }
}
