package com.bank.safestop;

import com.bank.safestop.explain.UnsafeStopExplainer;
import com.bank.safestop.ledger.Ledger;
import com.bank.safestop.worker.TransferWorker;

import java.util.logging.*;

public class DeprecatedThreadDemo {
    private static final Logger log = Logger.getLogger(DeprecatedThreadDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new SafeStopLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) throws Exception {
        UnsafeStopExplainer explainer = new UnsafeStopExplainer();
        explainer.whyStopIsUnsafe();
        explainer.whySuspendIsUnsafe();

        Ledger ledger = new Ledger();
        java.math.BigDecimal openingTotal = ledger.total();
        log.info(() -> "Opening ledger total = " + openingTotal);

        TransferWorker worker = new TransferWorker(ledger);
        Thread t = new Thread(worker, "transfer-pool-thread-1");
        t.start();

        Thread.sleep(50);
        worker.pause();               // safe pause (NOT suspend)
        Thread.sleep(20);
        // While paused, another thread can still read the ledger — no deadlock.
        log.info(() -> "During pause, ledger readable, total = " + ledger.total());
        worker.resumeWork();          // safe resume (NOT resume-after-suspend)

        Thread.sleep(50);
        log.info("Requesting clean stop (interrupt, NOT stop)");
        t.interrupt();                // safe stop (NOT Thread.stop)
        t.join(2000);

        java.math.BigDecimal closingTotal = ledger.total();
        log.info(() -> "Closing ledger total = " + closingTotal
                + " (invariant held = " + openingTotal.equals(closingTotal) + ")");
    }
}

