package com.bank.safestop;

import com.bank.safestop.ledger.Ledger;
import com.bank.safestop.worker.TransferWorker;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.*;

class SafeThreadControlTest {

    @Test
    void ledgerInvariantHeldAfterCleanStop() throws Exception {
        Ledger ledger = new Ledger();
        BigDecimal opening = ledger.total();
        TransferWorker worker = new TransferWorker(ledger);
        Thread t = new Thread(worker, "transfer-pool-thread-1");
        t.start();
        Thread.sleep(80);
        t.interrupt();                // safe stop
        t.join(2000);
        assertFalse(t.isAlive(), "worker must stop after interrupt");
        assertEquals(0, opening.compareTo(ledger.total()),
                "total money must be unchanged — no half-transfer corruption");
    }

    @Test
    void pauseReleasesLockSoOtherThreadsAreNotBlocked() throws Exception {
        Ledger ledger = new Ledger();
        TransferWorker worker = new TransferWorker(ledger);
        Thread t = new Thread(worker, "transfer-pool-thread-1");
        t.start();
        Thread.sleep(40);
        worker.pause();
        Thread.sleep(20);
        // A reader thread must NOT block during pause (no deadlock like suspend).
        BigDecimal[] read = new BigDecimal[1];
        Thread reader = new Thread(() -> read[0] = ledger.total(), "reader");
        reader.start();
        reader.join(1000);
        assertFalse(reader.isAlive(), "reader must not deadlock during pause");
        assertNotNull(read[0], "reader could read the ledger while worker paused");
        worker.resumeWork();
        t.interrupt();
        t.join(2000);
    }

    @Test
    void resumeContinuesProcessing() throws Exception {
        Ledger ledger = new Ledger();
        TransferWorker worker = new TransferWorker(ledger);
        Thread t = new Thread(worker, "transfer-pool-thread-1");
        t.start();
        Thread.sleep(30);
        worker.pause();
        int atPause = worker.completedPairs();
        Thread.sleep(20);
        worker.resumeWork();
        Thread.sleep(40);
        t.interrupt();
        t.join(2000);
        assertTrue(worker.completedPairs() >= atPause,
                "work must continue after resume, never corrupt");
    }
}
